/* Generates everything derived from the manifests:
     packages/contract/src/manifests/index.ts   the manifest registry
     packages/contract/manifest.json            the contract as JSON (PHP reads it)
     packages/svelte/src/lib/index.ts           the Svelte package's exports
   and (as they land) both runtimes' LLM stubs and the docs data.
   --check exits non-zero when a generated file is out of date. */
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '../../..');
const check = process.argv.includes('--check');
const HEADER = 'Generated by packages/contract/scripts/generate.ts — do not edit.';
const stale: string[] = [];

function emit(path: string, content: string): void {
    const file = join(root, path);
    const current = existsSync(file) ? readFileSync(file, 'utf8') : null;
    if (current === content) return;
    if (check) stale.push(path);
    else writeFileSync(file, content);
}

/* -------- manifest registry ----------------------------------------------- */
const manifestDir = join(root, 'packages/contract/src/manifests');
const names = readdirSync(manifestDir).filter((f) => f.endsWith('.ts') && f !== 'index.ts').map((f) => f.slice(0, -3)).sort();
const ident = (name: string) => name.replace(/[^a-zA-Z0-9]+(.)/g, (_, ch: string) => ch.toUpperCase()).replace(/^./, (ch) => ch.toLowerCase());

emit('packages/contract/src/manifests/index.ts', [
    `/* ${HEADER} */`,
    `import type { ComponentManifest } from '../schema.ts';`,
    ...names.map((name) => `import ${ident(name)} from './${name}.ts';`),
    '',
    `export const manifests: ComponentManifest[] = [${names.map(ident).join(', ')}];`,
    '',
    'export const registry: Record<string, ComponentManifest> = Object.fromEntries(manifests.map((m) => [m.name, m]));',
    '',
].join('\n'));

const manifests = await Promise.all(names.map(async (name) => (await import(pathToFileURL(join(manifestDir, `${name}.ts`)).href)).default));
for (const manifest of manifests) {
    if (!names.includes(manifest.name)) throw new Error(`Manifest file and name differ: ${manifest.name}`);
}

/* -------- contract JSON ----------------------------------------------------- */
const json = manifests.map(({ examples, ...rest }) => ({ ...rest, examples: examples.map((e: { label: string }) => ({ label: e.label })) }));
emit('packages/contract/manifest.json', JSON.stringify({ comment: HEADER, components: json }, null, 2) + '\n');

/* -------- Svelte exports ---------------------------------------------------- */
// `Button` → components/Button.svelte; `Dropdown.Item` → components/Dropdown.Item.svelte,
// attached to the Dropdown export; a namespace with no root component (Section,
// Chart) is a plain object.
const svelteNames: string[] = manifests.map((m) => m.svelte);
const roots = new Map<string, string[]>();
for (const path of svelteNames) {
    const [head, ...tail] = path.split('.');
    if (!roots.has(head)) roots.set(head, []);
    if (tail.length) roots.get(head)!.push(tail.join('.'));
}
const local = (path: string) => `${path.replace(/\./g, '_')}_`;
const lines = [`/* ${HEADER} */`];
for (const path of [...svelteNames].sort()) lines.push(`import ${local(path)} from './components/${path}.svelte';`);
lines.push('');
for (const [head, members] of [...roots.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    const hasRoot = svelteNames.includes(head);
    const parts = members.sort().map((member) => `${member}: ${local(`${head}.${member}`)}`).join(', ');
    if (!members.length) lines.push(`export const ${head} = ${local(head)};`);
    else if (hasRoot) lines.push(`export const ${head} = Object.assign(${local(head)}, { ${parts} });`);
    else lines.push(`export const ${head} = { ${parts} };`);
}
lines.push('', `export { sigta, ensureRuntime } from './runtime/runtime.js';`, `export { leave, arrive } from './runtime/transitions.js';`, '');
emit('packages/svelte/src/lib/index.ts', lines.join('\n'));

if (check && stale.length) {
    console.error(`Generated files are out of date — run npm run generate:\n  ${stale.join('\n  ')}`);
    process.exit(1);
}
console.log(check ? 'generate: up to date' : `generate: ${manifests.length} manifests`);
